// Período: de hoje até daqui a 6 dias, no horário de Brasília. A mensagem só sai no dia do aniversário,
// porque o texto do modelo diz "Hoje"; quem fez aniversário ontem não entra mais.
const ZONA = 'America/Sao_Paulo';
const hoje = DateTime.now().setZone(ZONA).startOf('day');
const datas = {};
for (let i = 0; i <= 6; i++) {
  const d = hoje.plus({ days: i });
  datas[d.toFormat('MM-dd')] = d.toISODate();
  // Quem nasceu em 29/02 recebe em 28/02 nos anos não bissextos.
  if (d.toFormat('MM-dd') === '02-28' && !d.isInLeapYear) datas['02-29'] = d.toISODate();
}
return [{ json: {
  de: hoje.toISODate(),
  ate: hoje.plus({ days: 6 }).toISODate(),
  periodo: hoje.toFormat('dd/MM') + ' a ' + hoje.plus({ days: 6 }).toFormat('dd/MM'),
  dias: Object.keys(datas),
  datas,
} }];

const ZONA = 'America/Sao_Paulo';
const linha = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const CATEGORIAS = { bronze: 'Bronze', prata: 'Prata', ouro: 'Ouro', legado: 'Diamante', diamante: 'Diamante' };
const renderizar = (texto, vars) => String(texto || '').replace(/\{\{(\d+)\}\}/g, (_, n) => vars[Number(n) - 1] ?? '');
function celular(v) {
  let n = String(v ?? '').replace(/\D/g, '').replace(/^0+/, '');
  if (n.length === 10 || n.length === 11) n = '55' + n;
  // Celular brasileiro sem o nono dígito: 55 + DDD + 8 dígitos começando em 6 a 9.
  if (/^55\d{2}[6-9]\d{7}$/.test(n)) n = n.slice(0, 4) + '9' + n.slice(4);
  return /^\d{12,15}$/.test(n) ? n : '';
}

const cfg = $('Ler configuração').first().json;
const periodo = $('Calcular período').first().json;
// O Base44 devolve { clientes: [...] }; se vier uma lista solta, o n8n já separou em itens.
const itens = $input.all().map((i) => i.json);
const clientes = itens.length === 1 && Array.isArray(itens[0].clientes) ? itens[0].clientes : itens.filter((c) => c && c.cliente_id);

const suporte = celular(cfg.whatsapp_suporte);
// Presente do mês do aniversário (tabela presentes_aniversario, tela Envios > Presentes de aniversário):
// o da categoria do cliente ou, sem ele, o de todas. Mês sem presente: o cliente não entra na fila.
const presentes = cfg.presentes && typeof cfg.presentes === 'object' ? cfg.presentes : {};
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
function presenteDo(dia, categoria) {
  const mes = dia.toFormat('yyyy-MM');
  const b = presentes[mes + ':' + categoria] || presentes[mes + ':todas'];
  // O modelo já põe o ponto depois do presente.
  const beneficio = b ? linha(b.beneficio).replace(/[.;,]+$/, '') : '';
  return beneficio && linha(b.regra) ? { beneficio, regra: linha(b.regra) } : null;
}
// Presente exclusivo de um cliente (mesma tela): vale uma vez, no lugar do presente do mês, mesmo num mês sem presente.
const exclusivos = cfg.exclusivos && typeof cfg.exclusivos === 'object' ? cfg.exclusivos : {};
function presenteExclusivo(clienteId) {
  const e = exclusivos[clienteId];
  const beneficio = e ? linha(e.beneficio).replace(/[.;,]+$/, '') : '';
  return beneficio && linha(e.regra) ? { beneficio, regra: linha(e.regra), id: Number(e.id) } : null;
}

const agora = DateTime.now().setZone(ZONA);
const [hIni, mIni] = String(cfg.janela_aniversario_inicio || '09:00').split(':').map(Number);
const [hFim, mFim] = String(cfg.janela_aniversario_fim || '12:00').split(':').map(Number);
const diasPermitidos = (Array.isArray(cfg.janela_aniversario_dias) ? cfg.janela_aniversario_dias : [1, 2, 3, 4, 5, 6, 7]).map(Number);

// Dia do envio: sempre o próprio aniversário, porque o texto do modelo diz "Hoje". Se esse dia da semana
// estiver fora de janela_aniversario_dias, o cliente não entra na fila. O enviador cancela o que não sair no dia.
// Horário sorteado dentro da janela, com 15 min de folga no fim. Se já passou, sai na próxima rodada.
function horario(dia) {
  const ini = dia.set({ hour: hIni, minute: mIni, second: 0, millisecond: 0 });
  const fim = dia.set({ hour: hFim, minute: mFim, second: 0, millisecond: 0 });
  const folga = Math.max(0, Math.floor(fim.diff(ini, 'minutes').minutes) - 15);
  const h = ini.plus({ minutes: Math.floor(Math.random() * (folga + 1)) });
  return h < agora ? agora : h;
}

const ignorados = { fora_do_periodo: 0, fora_da_janela: 0, inativo: 0, pj: 0, sem_celular: 0, centralizador: 0, repetido: 0, sem_aceite: 0, sem_nome: 0, sem_presente: 0 };
const mesesSemPresente = new Set();
const vistos = new Set();
// A mesma pessoa pode ter mais de um cadastro com o mesmo celular: só um recebe.
const telefones = new Set();
const fila = [];
for (const c of clientes) {
  const id = linha(c.cliente_id);
  const m = linha(c.aniversario).match(/(\d{2})-(\d{2})(?:T.*)?$/);
  const data = m ? periodo.datas[m[1] + '-' + m[2]] : null;
  if (!id || !data || vistos.has(id)) { ignorados.fora_do_periodo++; continue; }
  vistos.add(id);
  const dia = DateTime.fromISO(data, { zone: ZONA });
  if (!diasPermitidos.includes(dia.weekday)) { ignorados.fora_da_janela++; continue; }
  if (c.ativo === false) { ignorados.inativo++; continue; }
  if (linha(c.tipo_cliente).toUpperCase() === 'PJ') { ignorados.pj++; continue; }
  const telefone = celular(c.celular);
  if (!telefone) { ignorados.sem_celular++; continue; }
  if (suporte && telefone === suporte) { ignorados.centralizador++; continue; }
  if (telefones.has(telefone)) { ignorados.repetido++; continue; }
  telefones.add(telefone);
  if (cfg.exigir_aceite === true && c.aceita_comunicacao !== true) { ignorados.sem_aceite++; continue; }
  const nome = linha(c.primeiro_nome).split(' ')[0];
  if (!nome) { ignorados.sem_nome++; continue; }
  const categoria = CATEGORIAS[linha(c.categoria).toLowerCase()] || linha(c.categoria);
  const exclusivo = presenteExclusivo(id);
  const b = exclusivo || presenteDo(dia, categoria);
  if (!b) { ignorados.sem_presente++; mesesSemPresente.add(MESES[dia.month - 1] + ' de ' + dia.year); continue; }
  const variaveis = [nome, b.beneficio, b.regra];
  fila.push({
    ano: dia.year,
    cliente_id: id,
    telefone,
    primeiro_nome: nome,
    categoria: categoria || null,
    variaveis,
    texto: renderizar(cfg.texto_modelo_aniversario, variaveis),
    presente_exclusivo_id: exclusivo ? exclusivo.id : null,
    agendado_para: horario(dia).toUTC().toISO(),
  });
}

return [{ json: {
  periodo: periodo.periodo,
  total_base44: clientes.length,
  na_lista: fila.length,
  ignorados,
  meses_sem_presente: [...mesesSemPresente],
  exclusivos: fila.filter((f) => f.presente_exclusivo_id).length,
  fila,
} }];
